#!/usr/bin/env node
// PostToolUse hook for Edit/Write: run prettier on the file that was just changed.
// Uses the project's local prettier when one exists, otherwise prettier on PATH.
// Exit 2 on failure so the error is fed back to the agent.
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";

const input = JSON.parse(readFileSync(0, "utf8"));
const file = input?.tool_input?.file_path;
if (!file) process.exit(0);

function findLocalPrettier(from) {
  for (let dir = dirname(resolve(from)); ; dir = dirname(dir)) {
    const bin = join(dir, "node_modules", ".bin", "prettier");
    if (existsSync(bin)) return bin;
    if (dirname(dir) === dir) return null;
  }
}

const prettier = findLocalPrettier(file) ?? "prettier";

try {
  execFileSync(prettier, ["--write", "--ignore-unknown", file], {
    cwd: input.cwd,
    stdio: ["ignore", "pipe", "pipe"],
    timeout: 30_000,
  });
} catch (err) {
  process.stderr.write(`prettier failed on ${file}:\n${err.stderr ?? err.message}`);
  process.exit(2);
}

Matchers only see the tool name, and a Bash command is an opaque string. You can't reliably tell which file `sed -i`, `cat >`, `tee`, `python -c`, or a build step will touch by parsing it. So don't try to match the command. Instead, snapshot the repo's dirty files before each Bash call and format whatever changed after it. That catches every writer, including ones you haven't thought of.

**1. The script** (`.claude/hooks/bash-fmt.sh`, then `chmod +x`):

```bash
#!/usr/bin/env bash
# Usage: bash-fmt.sh snapshot|format   (hook JSON arrives on stdin)
# snapshot (PreToolUse, Bash): record content hashes of dirty files
# format   (PostToolUse, Bash): prettier-format files whose hashes changed
set -u
mode=$1
input=$(cat)
cd "$(jq -r '.cwd' <<<"$input")" || exit 0
git rev-parse --show-toplevel >/dev/null 2>&1 || exit 0

id=$(jq -r '.tool_use_id' <<<"$input")
state="${TMPDIR:-/tmp}/bash-fmt-$id"

# "<content-hash> <path>" for every modified or untracked file
dirty() {
  git status --porcelain --untracked-files=all | cut -c4- | while IFS= read -r f; do
    [ -f "$f" ] && printf '%s %s\n' "$(git hash-object -- "$f")" "$f"
  done | sort
}

if [ "$mode" = snapshot ]; then
  dirty > "$state"
  exit 0
fi

[ -f "$state" ] || exit 0
dirty > "$state.after"
# Lines only in "after" are new or changed since the snapshot
comm -13 "$state" "$state.after" | cut -d' ' -f2- |
  xargs -r -d '\n' prettier --write --ignore-unknown
rm -f "$state" "$state.after"
exit 0
```

Notes on the script:
- It uses `git hash-object`, so it works on macOS and Linux without `sha256sum` or `shasum`.
- A file that was already dirty before the command is formatted only if the command changed its content. Your in-progress edits are not reformatted just for being dirty.
- It assumes no spaces or quotes in filenames. `git status` quotes unusual names, so those files get skipped. Harmless, but worth knowing.
- It always exits 0, so a formatter failure never blocks Claude's work. Drop the trailing `exit 0` if you want a formatter error surfaced.
- It needs `jq` and `prettier` on PATH. Use `npx prettier` in the xargs line if prettier is project-local.

**2. The config** (`.claude/settings.json`), keeping your existing `Edit|Write` hook:

```json
{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          { "type": "command", "command": "\"$CLAUDE_PROJECT_DIR\"/.claude/hooks/bash-fmt.sh snapshot" }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          { "type": "command", "command": "<your existing prettier hook>" }
        ]
      },
      {
        "matcher": "Bash",
        "hooks": [
          { "type": "command", "command": "\"$CLAUDE_PROJECT_DIR\"/.claude/hooks/bash-fmt.sh format" }
        ]
      }
    ]
  }
}
```

Don't add `if: "Bash(sed*)"`. It would only cover the commands you name, which defeats the point. The `Bash` matcher runs on every Bash call, and the script returns quickly when nothing changed.

Then run `python3 "/home/claude/work/authoring-kit/skills/authoring-hooks/scripts/hooktool.py" validate .claude/settings.json` to check the config.

