// Mount this route before any global express.json() middleware.
// Signature verification needs the exact raw bytes Stripe sent.
app.post(
  '/webhooks/stripe',
  express.raw({ type: 'application/json' }),
  (req, res) => {
    const signature = req.headers['stripe-signature'];

    let event;
    try {
      event = stripe.webhooks.constructEvent(req.body, signature, webhookSecret);
    } catch (err) {
      console.error('Stripe webhook signature verification failed:', err.message);
      return res.status(400).send('Invalid signature');
    }

    if (event.type === 'payment_intent.succeeded') {
      const paymentIntent = event.data.object;

      // Log identifiers and amounts only, not the full object (it can contain PII).
      console.log('payment_intent.succeeded', {
        eventId: event.id,
        paymentIntentId: paymentIntent.id,
        amount: paymentIntent.amount,
        currency: paymentIntent.currency,
        customer: paymentIntent.customer,
        created: new Date(paymentIntent.created * 1000).toISOString(),
      });
    }

    // Acknowledge every event, including types you don't handle.
    // Any non-2xx response makes Stripe retry.
    res.json({ received: true });
  }
);

app.use(express.json());

app.listen(3000, () => console.log('Listening on :3000'));
```

Notes:

- **Raw body:** `express.raw()` is required. If `express.json()` parses the body first, `constructEvent` fails because the bytes no longer match the signed payload.
- **Secrets:** `STRIPE_WEBHOOK_SECRET` is the `whsec_...` value for this endpoint. For local testing, `stripe listen --forward-to localhost:3000/webhooks/stripe` prints a temporary one.
- **Responses:** A bad signature returns 400 and no event is processed. Other event types return 200 so Stripe doesn't retry them.
- **Idempotency:** Stripe can deliver the same event more than once. This handler only logs, so duplicates are harmless. If you later write to a database, dedupe on `event.id`.

I haven't run this against Stripe. To check it, send a test payment with `stripe trigger payment_intent.succeeded` while the listener is running.

