#!/usr/bin/env python3
"""PreToolUse hook: load the db-conventions skill before edits under src/db/."""
import json
import os
import re
import sys

SKILL_PATH = os.path.join(
    os.environ.get("CLAUDE_PLUGIN_ROOT", os.path.dirname(os.path.dirname(os.path.abspath(__file__)))),
    "skills", "db-conventions", "SKILL.md",
)
DB_PATH = re.compile(r"(^|/)src/db/")


def skill_body(path):
    with open(path, encoding="utf-8") as f:
        text = f.read()
    # Drop the YAML frontmatter; the rest is the instructions.
    if text.startswith("---"):
        parts = text.split("---", 2)
        if len(parts) == 3:
            text = parts[2]
    return text.strip()


def main():
    try:
        event = json.load(sys.stdin)
    except json.JSONDecodeError:
        return 0

    file_path = (event.get("tool_input") or {}).get("file_path", "")
    if not DB_PATH.search(file_path):
        return 0

    context = (
        "The file being edited is under src/db/. The db-conventions skill applies.\n\n"
        + skill_body(SKILL_PATH)
    )
    json.dump(
        {
            "hookSpecificOutput": {
                "hookEventName": "PreToolUse",
                "additionalContext": context,
            }
        },
        sys.stdout,
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())

