#!/usr/bin/env python3
"""Answer a question from the given text/markdown files, with exact citations.

Usage: cite.py "<question>" FILE [FILE ...]

Prints one JSON object to stdout:
  {"answer": "...", "citations": [{"cited_text", "source", "location"}]}

On any failure it prints {"error": "..."} instead and exits 1, so stdout is
always valid JSON. Diagnostics go to stderr only.
"""
import json
import sys
from pathlib import Path

import anthropic

MODEL = "claude-opus-5-5"
MAX_TOKENS = 16000
NOT_FOUND_MARKER = "INSUFFICIENT_SOURCES"
NOT_FOUND_ANSWER = "The provided files do not contain the information needed to answer this question."

SYSTEM = f"""You answer questions using only the documents provided in this conversation.
- Use only information stated in the documents. Do not use outside knowledge and do not guess.
- Every sentence you write must be supported by a cited passage from the documents.
- If the documents do not answer the question, reply with exactly "{NOT_FOUND_MARKER}" and nothing else.
- Keep the answer concise and in plain prose."""


class CiteError(Exception):
    pass


def load_sources(paths):
    if not paths:
        raise CiteError("no source files given")
    sources = []
    for raw in paths:
        path = Path(raw)
        if not path.is_file():
            raise CiteError(f"not a file: {raw}")
        try:
            # Read with universal newlines; the same text is sent to the API and
            # used to verify citations, so character offsets line up.
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            raise CiteError(f"not UTF-8 text: {raw}")
        if not text.strip():
            raise CiteError(f"empty file: {raw}")
        sources.append({"path": raw, "text": text})
    return sources


def build_content(sources, question):
    # Each file is its own plain-text document with citations enabled. The
    # question goes last, after the documents, as the API recommends.
    content = [
        {
            "type": "document",
            "title": src["path"],
            "source": {"type": "text", "media_type": "text/plain", "data": src["text"]},
            "citations": {"enabled": True},
        }
        for src in sources
    ]
    content.append({"type": "text", "text": question})
    return content


def resolve_citation(citation, sources):
    """Map an API citation to a passage in the provided files, verifying it."""
    if citation.type != "char_location":
        raise CiteError(f"unsupported citation type: {citation.type}")
    if not 0 <= citation.document_index < len(sources):
        raise CiteError("citation points outside the provided files")
    src = sources[citation.document_index]
    text = src["text"]
    start, end = citation.start_char_index, citation.end_char_index
    if text[start:end] != citation.cited_text:
        raise CiteError(f"citation does not match the text of {src['path']}")
    return {
        "cited_text": citation.cited_text,
        "source": src["path"],
        "location": {
            "type": "char_location",
            "start_char_index": start,
            "end_char_index": end,
            "start_line": text.count("\n", 0, start) + 1,
            "end_line": text.count("\n", 0, end) + 1,
        },
    }


def build_result(response, sources):
    """Turn a Messages response into the answer envelope, or raise CiteError."""
    if response.stop_reason == "refusal":
        raise CiteError("the model declined to answer")
    if response.stop_reason == "max_tokens":
        raise CiteError("the answer was truncated at max_tokens")

    text_blocks = [block for block in response.content if block.type == "text"]
    answer_text = "".join(block.text for block in text_blocks).strip()
    if answer_text == NOT_FOUND_MARKER:
        return {"answer": NOT_FOUND_ANSWER, "citations": []}

    citations, seen = [], set()
    for block in text_blocks:
        if not block.text.strip():
            continue
        if not block.citations:
            raise CiteError(f"uncited claim in answer: {block.text.strip()[:200]!r}")
        for citation in block.citations:
            resolved = resolve_citation(citation, sources)
            key = json.dumps([resolved["source"], resolved["location"]], sort_keys=True)
            if key not in seen:
                seen.add(key)
                citations.append(resolved)

    if not answer_text or not citations:
        raise CiteError("the answer has no citations")
    return {"answer": answer_text, "citations": citations}


def cite(question, paths, client=None):
    sources = load_sources(paths)
    client = client or anthropic.Anthropic()
    response = client.messages.create(
        model=MODEL,
        max_tokens=MAX_TOKENS,
        system=SYSTEM,
        messages=[{"role": "user", "content": build_content(sources, question)}],
    )
    return build_result(response, sources)


def main(argv):
    if len(argv) < 2 or not argv[0].strip():
        print('usage: cite.py "<question>" FILE [FILE ...]', file=sys.stderr)
        result, status = {"error": "usage: cite.py \"<question>\" FILE [FILE ...]"}, 1
    else:
        try:
            result, status = cite(argv[0], argv[1:]), 0
        except Exception as exc:  # any failure still produces a JSON object
            print(f"cite: {exc}", file=sys.stderr)
            result, status = {"error": str(exc)}, 1
    sys.stdout.write(json.dumps(result) + "\n")
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

