#!/usr/bin/env python3
"""Answer a question from local text/markdown files, with verified citations.

Usage:
    cite.py QUESTION FILE [FILE ...] [--model MODEL] [--max-tokens N]

On success, prints one JSON object to stdout and exits 0:
    {"answer": "...",
     "citations": [{"cited_text": "...", "source": "path/to/file.md",
                    "location": {"start_char": 0, "end_char": 10,
                                 "start_line": 1, "end_line": 1}}]}

On failure, prints {"answer": null, "citations": [], "error": "..."} and exits 1
(2 for bad arguments). Stdout always holds exactly one JSON document.

Citations come from the Anthropic Citations API, not from text the model writes.
Each one is checked against the file contents before it is printed: the
cited_text must equal the file's text at the reported character range. If any
answer text has no verified citation, the run fails instead of printing a
claim that is not traceable to the files.
"""

import argparse
import json
import sys
from dataclasses import dataclass

import anthropic

DEFAULT_MODEL = "claude-sonnet-5-5"
DEFAULT_MAX_TOKENS = 2048
NOT_FOUND = "NOT_FOUND"
NOT_FOUND_ANSWER = "The provided files do not contain an answer to this question."

SYSTEM_PROMPT = (
    "You answer questions using only the documents you are given. "
    "Do not use outside knowledge and do not guess. "
    "Every sentence that states a fact must be supported by citations to the documents. "
    "Be concise. If the documents do not contain the answer, respond with exactly "
    f"{NOT_FOUND} and nothing else."
)


class CiteError(Exception):
    """The run cannot produce a verified answer."""


@dataclass
class Source:
    path: str
    text: str


def load_source(path):
    try:
        # newline="" keeps the file's exact characters, so offsets match the file.
        with open(path, encoding="utf-8", newline="") as f:
            text = f.read()
    except UnicodeDecodeError:
        raise CiteError(f"{path} is not UTF-8 text")
    except OSError as e:
        raise CiteError(f"cannot read {path}: {e.strerror or e}")
    if "\0" in text:
        raise CiteError(f"{path} looks like a binary file")
    if not text.strip():
        raise CiteError(f"{path} is empty")
    return Source(path=path, text=text)


def build_messages(question, sources):
    content = [
        {
            "type": "document",
            "title": source.path,
            "source": {"type": "text", "media_type": "text/plain", "data": source.text},
            "citations": {"enabled": True},
        }
        for source in sources
    ]
    content.append({"type": "text", "text": question})
    return [{"role": "user", "content": content}]


def location(text, start, end):
    # Lines are 1-based. end is exclusive, so the last character is at end - 1.
    return {
        "start_char": start,
        "end_char": end,
        "start_line": text.count("\n", 0, start) + 1,
        "end_line": text.count("\n", 0, end - 1) + 1,
    }


def _unique_occurrence(haystack, needle):
    first = haystack.find(needle)
    if first == -1 or haystack.find(needle, first + 1) != -1:
        return None
    return first


def verify_citation(raw, sources):
    """Return (document_index, start, end) if the citation matches the file exactly, else None."""
    if getattr(raw, "type", None) != "char_location":
        return None  # page or block locations do not apply to plain-text documents
    index = getattr(raw, "document_index", None)
    cited = getattr(raw, "cited_text", None)
    start = getattr(raw, "start_char_index", None)
    end = getattr(raw, "end_char_index", None)
    if not (isinstance(index, int) and 0 <= index < len(sources)):
        return None
    if not (isinstance(cited, str) and cited and isinstance(start, int) and isinstance(end, int)):
        return None

