        # Offsets are off, but the quote may still identify one exact passage.
        # Relocate only when it occurs exactly once, so the match is unambiguous.
        found = _unique_occurrence(text, cited)
        if found is None:
            return None
        start, end = found, found + len(cited)
    return index, start, end


def build_result(response, sources):
    if getattr(response, "stop_reason", None) == "max_tokens":
        raise CiteError("answer was cut off at max_tokens; rerun with a larger --max-tokens")

    blocks = [b for b in response.content if getattr(b, "type", None) == "text"]
    full_text = "".join(b.text for b in blocks).strip()
    if full_text == NOT_FOUND and not any(b.citations for b in blocks):
        return {"answer": NOT_FOUND_ANSWER, "citations": []}

