#!/usr/bin/env python3
"""Answer a question from the internal knowledge base, with per-statement citations.

Runs search_kb.py for the question, passes each hit to Claude as a document block
with citations enabled, and prints the answer with every statement tied to the
hit(s) it was drawn from. Hits are fetched fresh on every call.

Usage:
    python answer_kb.py "how do we rotate the billing API key?"
    python answer_kb.py --json "how do we rotate the billing API key?"
"""

import argparse
import json
import subprocess
import sys
from pathlib import Path

import anthropic

SEARCH_SCRIPT = Path(__file__).with_name("search_kb.py")
DEFAULT_MODEL = "claude-sonnet-5-5"

SYSTEM = (
    "Answer the question using only the provided documents. "
    "If the documents do not contain the answer, say so. "
    "Do not add anything from outside the documents."
)


def search(question):
    """Run search_kb.py and return its list of {"title", "url", "text"} hits."""
    proc = subprocess.run(
        [sys.executable, str(SEARCH_SCRIPT), question],
        capture_output=True,
        text=True,
        check=False,
    )
    if proc.returncode != 0:
        raise RuntimeError(f"search_kb.py failed: {proc.stderr.strip()}")
    return json.loads(proc.stdout)


def to_document(hit):
    """One hit as a citable document block. Its position in the request is its index."""
    return {
        "type": "document",
        "source": {"type": "text", "media_type": "text/plain", "data": hit["text"]},
        "title": hit["title"],
        "citations": {"enabled": True},
    }


def ask(question, hits, model):
    client = anthropic.Anthropic()
    response = client.messages.create(
        model=model,
        max_tokens=2048,
        system=SYSTEM,
        messages=[
            {
                "role": "user",
                "content": [
                    *(to_document(hit) for hit in hits),
                    {"type": "text", "text": question},
                ],
            }
        ],
    )
    if response.stop_reason == "max_tokens":
        print("warning: answer was truncated at max_tokens", file=sys.stderr)
    return response


def build_statements(response):
    """Group the response's text blocks into statements, each with its sources.

    The API splits text at citation boundaries, so consecutive blocks that cite the
    same hits are merged back into one statement. Blocks with no citations form an
    unsourced statement, which is kept so that unsupported claims stay visible.
    """
    statements = []
    for block in response.content:
        if block.type != "text" or not block.text.strip():
            continue
        sources = {}
        for citation in block.citations or []:
            sources.setdefault(citation.document_index, []).append(
                citation.cited_text.strip()
            )
        if statements and statements[-1]["sources"].keys() == sources.keys():
            statements[-1]["text"] += block.text
            for index, quotes in sources.items():
                statements[-1]["sources"][index].extend(quotes)
        else:
            statements.append({"text": block.text, "sources": sources})
    for statement in statements:
        statement["text"] = statement["text"].strip()
    return statements


def build_output(statements, hits):
    """Shape the answer for display: hits are numbered in search order, [n] = hits[n-1]."""
    used = sorted({index for s in statements for index in s["sources"]})
    return {
        "statements": [
            {
                "text": s["text"],
                "sources": [index + 1 for index in sorted(s["sources"])],
            }
            for s in statements
        ],
        "sources": [
            {
                "n": index + 1,
                "title": hits[index]["title"],
                "url": hits[index]["url"],
                "quotes": list(
                    dict.fromkeys(
                        quote for s in statements for quote in s["sources"].get(index, [])
                    )
                ),
            }
            for index in used
        ],
    }


def render(output):
    lines = []
    for statement in output["statements"]:
        marks = "".join(f"[{n}]" for n in statement["sources"]) or "[unsourced]"
        lines.append(f"{statement['text']} {marks}")
    lines.append("")
    lines.append("Sources:")
    for source in output["sources"]:
        lines.append(f"[{source['n']}] {source['title']}")
        lines.append(f"    {source['url']}")
        for quote in source["quotes"]:
            lines.append(f"    > {quote}")
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("question")
    parser.add_argument("--model", default=DEFAULT_MODEL)
    parser.add_argument("--json", action="store_true", help="print JSON instead of text")
    args = parser.parse_args()

    hits = search(args.question)
    if not hits:
        print("No knowledge-base hits for that question.")
        return

    response = ask(args.question, hits, args.model)
    output = build_output(build_statements(response), hits)
    print(json.dumps(output, indent=2) if args.json else render(output))


if __name__ == "__main__":
    main()
